import{_ as s,o as i,c as t,a3 as r,j as e,a as u}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-kurse-zuweisen-gp.png",p="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-kurse-zuweisen-filtern.png",l="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-kurse-zuweisen-speicheroptionen.png",d="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-kurse-zuweisen-gefiltert.png",f=JSON.parse('{"title":"Kurse tabellarisch einer Schülergruppe zuweisen","description":"","frontmatter":{"title":"Kurse tabellarisch einer Schülergruppe zuweisen","source_pageid":1664,"source_revision":7168},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/kurse-zuweisen-gruppenprozesse-faecher.md","filePath":"schild3/suchen-gruppenprozesse/kurse-zuweisen-gruppenprozesse-faecher.md"}'),h={name:"schild3/suchen-gruppenprozesse/kurse-zuweisen-gruppenprozesse-faecher.md"};function o(c,n,g,z,m,w){return i(),t("div",null,[...n[0]||(n[0]=[r('<h1 id="kurse-tabellarisch-einer-schulergruppe-zuweisen" tabindex="-1">Kurse tabellarisch einer Schülergruppe zuweisen <a class="header-anchor" href="#kurse-tabellarisch-einer-schulergruppe-zuweisen" aria-label="Permalink to &quot;Kurse tabellarisch einer Schülergruppe zuweisen&quot;">​</a></h1><p>Wählen Sie Schülergruppe, Lernabschnitt und passende Kursfilter. Anschließend ordnen Sie die vorbereiteten Kurse in der Tabelle zu.</p><h2 id="_1-vorbereitungen" tabindex="-1">1. Vorbereitungen <a class="header-anchor" href="#_1-vorbereitungen" aria-label="Permalink to &quot;1. Vorbereitungen&quot;">​</a></h2><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-kurse-zuweisen-gp.png"><img src="'+a+'" alt="Weisen Sie unter &quot;Gruppenprozesse ➜ Fächer&quot; Kurse tabellarisch zu." loading="lazy"></a></p><p><em>Weisen Sie unter &quot;Gruppenprozesse ➜ Fächer&quot; Kurse tabellarisch zu.</em></p><p>Um Kurse tabellarisch zuzuweisen, wählen Sie zuerst im Schülercontainer die Gruppe aus, für die Sie Kurse zuweisen möchten. In der Regel ist dies eine Klasse, mehrere bestimmte Klassen oder ein Jahrgang.</p><p>Starten Sie anschließend unter <strong>Gruppenprozesse ➜ Fächer</strong> den Gruppenprozess <strong>Kurse zuweisen</strong>.</p><p>Es öffnet sich eine Übersicht, mit allen Kursen, die für die ausgewählte Schülergruppe im <em>Katalog Kurse</em> definiert wurden.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-kurse-zuweisen-filtern.png" title="Wählen Sie den passenden Lernabschnitt und filtern Sie die zur Verfügung stehenden Kurse."><img src="'+p+'" alt="Wählen Sie den passenden Lernabschnitt und filtern Sie die zur Verfügung stehenden Kurse." loading="lazy"></a></p><p>Grenzen Sie die Liste über <strong>Fach</strong>, <strong>Kursart</strong> oder <strong>Fachgruppe</strong> auf die benötigten Kurse ein.</p><p>Stellen Sie zuerst sicher, dass Sie das passende <em>Jahr und Abschnitt</em> eingestellt haben, für die Kurse zugewiesen werden sollen.</p>',11),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),u("Tipp")]),e("p",null,"Nehmen Sie hier die Möglichkeit von SchILD-NRW 3 zur Kenntnis, dass auch Kurse für einen in der Zukunft liegenden Lernabschnitt zugewiesen werden können.")],-1),r('<p>Passen Sie die <strong>Sortierung</strong> der Schülerliste an Ihre Planungsunterlagen an. Sind beispielsweise mehrere Klassen in einer alphabetischen Kursliste zusammengefasst, wählen Sie auch hier die Sortierung nach <strong>Name</strong>.</p><p>Die Kurse können über <strong>Sortierung Kurse</strong> entweder nach Ihrer <em>Kursbezeichnung</em> oder dem Fach sortiert werden.</p><p>In den folgenden drei Feldern stellen Sie die gewünschte Filterung ein. Sie können nach <strong>Fach</strong> und/oder <strong>Kursart</strong> filtern lassen, so dass nur Kurse angezeigt werden, die beide Filterbedingungen erfüllen.</p><p>Soll der gesetzte Inhalt eines Dropdown-Menüs gelöscht werden, markieren Sie den Inhalt und drücken Sie <code>Entf</code>.</p><p>Um die Filter tatsächlich anzuwenden, klicken Sie auf <code>Daten aktualisieren</code>. Im Anschluss werden nur die gewählten Kurse angezeigt.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-kurse-zuweisen-speicheroptionen.png" title="Stellen Sie die Speicheroptionen ein."><img src="'+l+'" alt="Stellen Sie die Speicheroptionen ein." loading="lazy"></a></p><p>Bevor Sie nun Kurse zuweisen, kontrollieren Sie die <em>Speicheroptionen&#39;</em>.</p><p>Hier wird eingestellt, wie sich der Gruppenprozess verhält, wenn es das Fach - ohne Kurszuweisung - in den Leistungsdaten schon gibt. Je nach Einstellung</p><ul><li>wird das Fach um die Kursangabe ergänzt</li><li>es wird ein zusätzliches neues Fach gleicher Art erzeugt, in das die Kursangabe eingetragen wird</li><li>es kommt zu keiner Änderung</li></ul><p>In der Regel bietet es sich an, das Fach um die Kursangabe zu ergänzen.</p><p>Über den Haken bei <strong>Fach beim Schüler löschen, wenn Kurs entfernt wird</strong> wird gesteuert, ob Fächer mit dem Abwählen eines Kurses mit gelöscht werden oder als kursloses Fach in den Leistungsdaten erhalten bleibt.</p><p>Mit dem Knopf <code>In Leistungsdaten übernehmen</code> wird die vorgenommene Zuordnung in die Schülerdatensätze geschrieben. Wenn Sie diesen Gruppenprozess schließen, bevor Sie die Änderungen eintragen, werden die Leistungsdaten nicht verändert.</p><h2 id="_2-kurse-zuweisen" tabindex="-1">2. Kurse zuweisen <a class="header-anchor" href="#_2-kurse-zuweisen" aria-label="Permalink to &quot;2. Kurse zuweisen&quot;">​</a></h2><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-kurse-zuweisen-gefiltert.png"><img src="'+d+'" alt="Der angewendete Filter generiert hier die Ansicht auf das Fach &quot;Englisch&quot; (E)." loading="lazy"></a></p><p><em>Der angewendete Filter generiert hier die Ansicht auf das Fach &quot;Englisch&quot; (E).</em></p><p>Hier im Beispiel wurde an einer Gesamtschule auf das <em>Fach Englisch</em> gefiltert. Dieses steht nun in der oberen Zeile über den <em>Jahrgang 10</em>.</p><p>In der Zeile darunter stehen die <em>Kursarten</em> für den <em>E-Kurs (E)</em> und den <em>G-Kurs (G)</em>.</p><p>Sie können nun bei den Schüler-Zeilen in eine Spalte klicken und dort Kurse zuweisen. Es wird jeweils die gewählte Kursart angezeigt.</p><p>Es ist möglich, mehrere Kurse in einer Zeile anzuwählen.</p><p>Dies macht hier im Beispiel bei Englisch für den E- oder G-Kurs die exklusiv zu belegen sind, keinen Sinn. Sie könnten über diesen Gruppenprozess jedoch zum Beispiel auch Arbeitsgemeinschaften, die als Kurse verwaltet werden, bei den Schülern eintragen. Damit währen Mehrfachbelegungen je nach Wahl und Lage der AGn möglich.</p><p>Denken Sie daran, zum Abschluss der Arbeiten auf <code>In Leistungsdaten übernehmen</code> anzuklicken.</p><p>Haben Sie Änderungen vorgenommen und nicht gespeichert, erscheint eine Textmeldung, in der nachgefragt wird, ob die Änderungen verworfen werden sollen.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Kurse_zuweisen_(Gruppenprozesse_F%C3%A4cher)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7168.</p>',24)])])}const S=s(h,[["render",o]]);export{f as __pageData,S as default};
